lp=ROOT/'evidence/conversion-ledger.json';data=json.loads(lp.read_text());entry=next(e for e in data['entries'] if e['id']=='ITEM-PESTLE');assert data['active_entry']==entry['id'] and not entry.get('generation_ready')
