shutil.copyfile(ROOT/fits[0]['current_registration']['plate']['path'],HERE/'body-fittings-comparison.png')
for step,action in [('resolve_item_identity_description_palette','Resolved installed/runtime stone bulb dusted with humoric powders, exact original tile and independent native y/Y tint roles.'),('verify_every_body_fitting_log','Reconciled sole Nima source-bound reusable fitting through original/reference/construction/contextual refinement, programmatic full material/masks, grip correction and intended-size views. Mutation hand placement and resting/ready poses remain pending.')]:entry['process_log'].append(dict(timestamp=datetime.now(timezone.utc).isoformat(),step=step,action=action,inputs=[ref(sourcepath)]+[e['current_registration']['model'] for e in fits],outputs=[ref(HERE/'fittings.json'),ref(HERE/'body-fittings-comparison.png')],review=review,result='PASS',new_imagegen_call=False))
entry.update(status='UNFINISHED',generation_ready=True,current_step='record_item_acceptance_from_all_fittings',current_registration=dict(model=ref(HERE/'fittings.json'),plate=ref(HERE/'body-fittings-comparison.png')),art_review=dict(status='PASS',reason=review),registration_summary='Pestle reusable source and sole ordinary-base fitting generation-ready; lower item-space grip, full stone, separate powder and original hand retained. Actual Hand181/6 mutation placement and weapon pose/native acceptance remain unfinished.',native_acceptance='Pending full-set generation gate, mutation-hand placement and weapon pose/equipment state',known_issues=['Actual mutation-managed Hand181/6 placement, resting/ready pose, named appearance/outfit and native equipment acceptance remain unfinished.'])
n=next(e for e in data['entries'] if e['id']=='FIT-YRAME-VIBRO-BLADE-HAND-2');assert n['status']=='UNFINISHED' and not n.get('generation_ready');n.update(status='IN PROGRESS',current_step='source_identity_description_slot_laterality');data['active_entry']=n['id'];data['updated_at']=datetime.now(timezone.utc).isoformat();write(lp,data)
